#!/usr/bin/env bash
#
# Records key pairs generated by OpenSSL as test vectors: for each NIST
# curve, private scalars d and their public points Q = d G; for Ed25519,
# seeds and their public keys. baldssl-crypto's tests recompute them.
#
# Usage:
#   scripts/gen-ec-vectors.sh <path/to/openssl> > tests/fixtures/keys/keypairs.txt
#

set -euo pipefail

if [[ "$#" -ne 1 ]]; then
    echo "usage: $0 <openssl>" >&2
    exit 2
fi
OPENSSL=$1
WORK=$(mktemp -d "${TMPDIR:-/tmp}/baldssl-ec.XXXXXX")
trap 'rm -rf "$WORK"' EXIT

# The hexadecimal block after a "<label>:" line of `pkey -text`.
block() {
    awk -v label="$1:" '
        $1 == label { on = 1; next }
        on && /^ +[0-9a-f:]+$/ { gsub(/[ :]/, ""); printf "%s", $0; next }
        on { exit }
    ' "$2"
}

echo "# Test vectors only: private keys generated for these tests and"
echo "# published here. Format: <curve> <private hex> <public hex>, the"
echo "# public key as an uncompressed point, or RFC 8032's encoding for ED25519."
echo "# Generated by scripts/gen-ec-vectors.sh with $("$OPENSSL" version)."
for curve in P-256 P-384 P-521; do
    for i in 1 2 3 4; do
        key="$WORK/$curve-$i.pem"
        "$OPENSSL" genpkey -algorithm EC -pkeyopt "ec_paramgen_curve:$curve" \
            -out "$key" 2>/dev/null
        "$OPENSSL" pkey -in "$key" -noout -text >"$WORK/text"
        echo "$curve $(block priv "$WORK/text") $(block pub "$WORK/text")"
    done
done
for i in 1 2 3 4; do
    key="$WORK/ed25519-$i.pem"
    "$OPENSSL" genpkey -algorithm ED25519 -out "$key" 2>/dev/null
    "$OPENSSL" pkey -in "$key" -noout -text >"$WORK/text"
    echo "ED25519 $(block priv "$WORK/text") $(block pub "$WORK/text")"
done
